{
  "name": "opencode-branch-context-guard",
  "version": "0.1.2",
  "description": "A tiny OpenCode TUI plugin that detects branch context drift during AI Coding sessions.",
  "license": "MIT",
  "author": "corysun",
  "keywords": ["opencode", "opencode-plugin", "tui", "git", "branch"],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/coryshipit/opencode-branch-context-guard.git"
  },
  "bugs": {
    "url": "https://github.com/coryshipit/opencode-branch-context-guard/issues"
  },
  "homepage": "https://github.com/coryshipit/opencode-branch-context-guard#readme",
  "engines": {
    "node": ">=18"
  },
  "type": "module",
  "exports": {
    "./tui": {
      "import": "./tui.mjs"
    }
  },
  "files": ["src", "tui.mjs", "README.md", "CHANGELOG.md", "docs", "LICENSE"],
  "scripts": {
    "deploy:atdd": "node scripts/deploy-atdd.mjs",
    "typecheck": "tsc --noEmit",
    "test": "tsx --test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.16",
    "@opentui/solid": "^0.5.1",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opentui/core": "^0.5.1",
    "@opentui/keymap": "^0.5.1",
    "@types/node": "^26.2.0",
    "tsx": "^4.20.3",
    "typescript": "^7.0.2"
  }
}
